        "lines": [
          {
            "who": "narrator",
            "text": "你站在原地。他像是挣扎了很久，终于穿过人群向你走来，在离你一步的地方停下。星光从穹顶落下来，落在他的睫毛上。"
          },
          {
            "who": "azhe",
            "text": "「今天的星光，」他看着天，声音很轻，「比排练室的灯好看。」（顿了很久）「跟你一起看的话——更好看。」"
          },
          {
            "who": "narrator",
            "text": "说完这句话，他像是用完了全身的力气，眼神飘向别处，手却诚实地没有走。你看见他的手在微微发抖——和他每次翻谱前试页边时一样稳，又一样抖。"
          }
        ],
