        "lines": [
          {
            "who": "narrator",
            "text": "演出视频火了，火的方式却不对。深夜，一条帖子被顶了上来：《起底某乐团女团长：暧昧管理，靠异性好感上位》。配图是十元和不同男乐手的合照——阿喆的水果、TIM 的勾肩、黄奕兴的车。"
          },
          {
            "who": "shiyuan",
            "text": "评论区一夜之间长出獠牙。十元把手机扣在谱架上，笑着说「没事，清者自清」，可那天下午的排练，她拉错了七个音。"
          }
        ],
