        "artText": "她不在。台阶上坐着一个戴眼镜的男人，斯文，干净，脚边放着还热乎的早餐——两份。 「你好。」他站起身，推了推眼镜，「奕兴。她……昨晚受了惊，我陪她到天亮，刚送她上楼补觉。」他顿了顿，目光在你手里的早餐上停了一秒，「你也给她带了？……心意很像。难怪。」 你站在原地，忽然明白自己差在哪里——不是早餐，是差在每一个「她需要」的时刻，他都在场。",
