        "lines": [
          {
            "who": "narrator",
            "text": "复习的第三个晚上，琴房热闹了起来：雪子拎着奶茶来探班，飞鸿来喊宝石对歌，REK 把贝斯搬回来说是「补上次那场演出」。"
          },
          {
            "who": "narrator",
            "text": "十元被挤在谱架前继续背题，雪子把吸管插好递到她嘴边，宝石和飞鸿为一小节和声争得面红耳赤。你看着这一屋子人，忽然觉得——她想要的乐团，大概就是这个样子。"
          },
          {
            "who": "shiyuan",
            "text": "散场后，十元悄悄拉住你：「等考完，我请你们所有人吃饭。……第一个请。」"
          }
        ],
