        "lines": [
          {
            "who": "narrator",
            "text": "工作室就这样开了起来。你谈下的第一个合作，是给星海的考生免费提供模拟面试——你没告诉十元，那家机构是你跑了四趟才谈下来的。"
          },
          {
            "who": "narrator",
            "text": "你开始在两条战线上作战：白天是老板，晚上是老师。累是真的累。可每次十元解出一道题抬头冲你笑的时候，你觉得这买卖，不亏。"
          }
        ],
