            "text": "（眼睛都亮了：）「真的啊？！哈哈，你说的啊，骗人是小狗！」 宝石的眼睛本来就有些下垂，这会儿亮晶晶的，像一只比熊。飞鸿觉得自己心跳漏了一拍，随即警铃大作——\n\n（我别是有病吧。）他面无表情地扒了口意面。（对着个哥们，我心动个屁。）\n\n彼时的他还不明白，有一种心跳，意味着情谊明媚。只觉得心，有点疼。",
