        "lines": [
          {
            "who": "narrator",
            "text": "你没能集齐足够的助力。宝石去找过，也唱过，可线索一条条断掉——没有人把那个对的时机递到他手里。"
          },
          {
            "who": "narrator",
            "text": "两年后，山丘重新装修。你路过旧舞台，看见公告栏上贴着两张泛黄的演出照：一张是两个人的合影，一张是一个人的独唱。"
          },
          {
            "who": "narrator",
            "text": "独唱那张的海报上写着：《爱我还是他》。主办方的名字，是宝石。可你知道吗，从那之后，这首歌他再也没有唱完过。"
          }
        ],
