        "lines": [
          {
            "who": "narrator",
            "text": "演出日。大巴上，小垃发了一条朋友圈：「婚礼民工的一天图文直播。」"
          },
          {
            "who": "narrator",
            "text": "配图是乐团众人，空格坐在角落，抱着一个看起来很旧的琴盒。"
          },
          {
            "who": "narrator",
            "text": "到了酒店，空格打开琴盒，脸色变了。"
          },
          {
            "who": "kongge",
            "text": "「……」"
          },
          {
            "who": "kongge",
            "text": "「光带衣服了。」"
          },
          {
            "who": "narrator",
            "text": "全场安静了一秒。"
          },
          {
            "who": "kongge",
            "text": "「琴没带。」"
          },
          {
            "who": "narrator",
            "text": "酒狂狂第一个笑出声：「琴呢？」"
          },
          {
            "who": "narrator",
            "text": "Tim没笑。他放下自己的琴盒，掏出手机，打开地图App。"
          },
          {
            "who": "tim",
            "text": "「格老，你在闲鱼上租的琴，地址给我。我现在去取。」"
          },
          {
            "who": "kongge",
            "text": "「啊？」"
          },
          {
            "who": "tim",
            "text": "「你不是说你在闲鱼上收了把88块的琴？3/4的？」"
          },
          {
            "who": "kongge",
            "text": "「……你怎么知道？」"
          },
          {
            "who": "tim",
            "text": "（笑了一下：）「你什么事我不知道。」"
          },
          {
            "who": "narrator",
            "text": "十分钟后，Tim联系好了闪送。三十分钟后，一把3/4的琴送到了酒店大堂。"
          },
          {
            "who": "narrator",
            "text": "Tim检查了一下琴的弓毛，递给空格。"
          },
          {
            "who": "tim",
            "text": "「先用我的备用弓。弦我帮你调好了。」"
          }
        ],
