            "contextBefore": "「下一季，还来吗？」",
            "contextAfter": "下一季，你来了。Tim也来了。\n\n你们之间一切如昨，又似乎更有默契。你们是一起对音准的搭档，是一起打羽毛球的球友，是他换头像时第一个告知“我换头像了免得你误会”的朋友。\n\n他依旧对你好，对所有人都好。但你不再计较了。\n\n有一次排练完，他递给你一瓶乌龙茶，忽然说：「跟你待着挺舒服的。不用想太多。」"
