        "lines": [
          {
            "who": "narrator",
            "text": "八月中，大鹅接到一个好机会——电视台的青年音乐会直播，一段键盘独奏。酬劳不高，但曝光难得。直播前三天，他退出了。"
          },
          {
            "who": "narrator",
            "text": "原因后来才传开：节目组要求全场假弹，放录音对口型，理由是「直播不能出事故」。大鹅在群里发了很长一段话，最后一句是："
          },
          {
            "who": "goose",
            "text": "「我可以弹错，但不能对着镜头假装自己在弹。那是直播，不是演戏。」"
          },
          {
            "who": "narrator",
            "text": "节目组把他的退出公告写得阴阳怪气，字里行间都是「某键盘手缺乏职业精神」。有营销号跟进，评论区乌烟瘴气。群里吵成一团。"
          },
          {
            "who": "rek",
            "text": "（在群里发了一串省略号：）「……这圈子，什么时候连真弹都成错了。」"
          },
          {
            "who": "shiyuan",
            "text": "（私信你：）「你去看看他。他现在谁的消息都不回。」"
          }
        ],
