        "lines": [
          {
            "who": "narrator",
            "text": "中秋后，大鹅的替补键盘手小周来了。技术不错，人缘一般，说话总带着一点若有若无的酸味。"
          },
          {
            "who": "narrator",
            "text": "这天他热情地拉着小塔：「塔哥，我表哥有个新场地，你去试试音？友情价。」"
          },
          {
            "who": "xiaozhou",
            "text": "「一个月才八千，还包水电。塔哥你打鼓那么费场地，这个价外面找不到的。」"
          },
          {
            "who": "narrator",
            "text": "你查了一下那个「友情价」——同地段市价的两倍半，还是毛坯房，合同里埋着一行小字：设备损坏照价赔偿，定价权归场地方。"
          },
          {
            "who": "narrator",
            "text": "小塔为人老实，已经在收拾鼓棒了。"
          }
        ],
