        "lines": [
          {
            "who": "narrator",
            "text": "曼波杯决赛的报名表摆在桌上，名单那一栏空着。填谁，不填谁，全团吵了三天。这一次，你没有急着表态。"
          },
          {
            "who": "narrator",
            "text": "你把这八个月的东西一样一样摆出来：路演的观众数、歌友会的上座率、摇人帖的转发、每一次救场的记录。"
          },
          {
            "who": "player",
            "text": "「宝石和飞鸿的原创 demo，我这有十一首。慢，是因为每一首都改了十几版。慢不是错。」"
          },
          {
            "who": "dayang",
            "text": "（盯着那叠 demo 看了很久，忽然把笔一摔：）「……行。是我短视了。名单，重写。」"
          },
          {
            "who": "narrator",
            "text": "报名表交上去那天，宝石和飞鸿的名字在名单正中间。宝石看到表的时候别过头去，飞鸿拍了拍他的背，什么都没说。"
          }
        ],
