        "lines": [
          {
            "who": "narrator",
            "text": "歌友会散场，十元张罗宵夜：「吃什么？火锅还是探鱼？」"
          },
          {
            "who": "feihong",
            "text": "（脱口而出：）「探鱼呗，宝石喜欢。」"
          },
          {
            "who": "narrator",
            "text": "他说完自己顿了一下，补了句：「……我是说，上回那家不错。」"
          },
          {
            "who": "narrator",
            "text": "你环视全桌——也只有他记得，宝石不吃香菜，所以他的蘸料碟里，从来不会出现香菜。"
          }
        ],
