        "title": "回忆 · 烤串摊",
        "sub": false,
        "need": {
          "bond": 0,
          "score": 0,
          "flags": []
        },
        "lines": [
          {
            "who": "narrator",
            "text": "那晚散场后，大家照例宵夜烤串。宝石很自然地把自己烤好的肉串分了一半给飞鸿——这本来没什么，他们一直这样。"
          },
          {
            "who": "narrator",
            "text": "可那天，飞鸿盯着那半把肉串看了两秒，幽幽地说了一句："
          },
          {
            "who": "feihong",
            "text": "「干嘛。又给十元提供素材啦？」"
          },
          {
            "who": "narrator",
            "text": "满桌哄笑，宝石捶了他一拳。只有足够留意的人才会发现：飞鸿说完这句话，把那半把肉串，一根不剩地，全吃了。"
          }
        ],
