        "lines": [
          {
            "who": "narrator",
            "text": "你决定找飞鸿谈谈。可是怎么开口呢？这天排练完，你在他身边游荡了三圈，欲言又止。"
          },
          {
            "who": "feihong",
            "text": "（还是他先开的口，头也不抬：）「你有啥事直说吧。最近看你怪怪的。」"
          }
        ],
