        "lines": [
          {
            "who": "narrator",
            "text": "十二月初，大羊把你叫到 chewing gum 酒馆。他没带吉他，就带了两杯啤酒。"
          },
          {
            "who": "dayang",
            "text": "（他难得没绕弯子：）「我谈过挺多恋爱。不在乐队圈里找，分手麻烦，坏名声。」"
          },
          {
            "who": "dayang",
            "text": "（他顿了顿，转着杯子：）「但最近我想明白一件事——名声是弹出来的，不是藏出来的。就像你，八个月前谁认识你？现在整个圈子都知道 GUSHI 有个靠谱实习生。」"
          },
          {
            "who": "narrator",
            "text": "他看着你，眼神是你从没见过的认真。"
          },
          {
            "who": "dayang",
            "text": "「所以我想破个例。跟你。」"
          }
        ],
