        "lines": [
          {
            "who": "narrator",
            "text": "小塔老家在海边。头天晚上，卤鹅、蚝烙、手打牛肉丸摆了满满一桌，阿姨还往你碗里舀了一勺沙茶酱，说「食饱未」。第二天，小英拉着你去逛市集，转角撞上一个正在画海的男人——画板上是整片整片的蓝。"
          },
          {
            "who": "narrator",
            "text": "他抬起头，说了句什么。海风太大，你没听清。但他把画送给了你，背面写着电话。"
          },
          {
            "who": "narrator",
            "text": "回程的车上，小英靠着小塔睡着了。你看着手里的画，忽然觉得这个冬天一点都不冷。"
          }
        ],
