        "lines": [
          {
            "who": "narrator",
            "text": "曼波杯冠军。颁奖词写了很多，你只记得一句：「这是一支从排练室里长出来的乐队。」"
          },
          {
            "who": "narrator",
            "text": "三个月后，商业化合约落地。签字那天，十元把乐团的名字改了——「哈基米曼波乐队」。曼波，是布鲁斯里最让人想跳舞的节奏。"
          },
          {
            "who": "shiyuan",
            "text": "（她把笔递给你：）「运营总监，签字吧。」"
          },
          {
            "who": "narrator",
            "text": "你握着笔，忽然想起八个月前那个信奉「差不多就行」的自己。原来所谓成长，不是变成了另一个人，而是终于敢把自己手里的每一件事，做到底。"
          }
        ],
